nginx_config:
daemon off;
master_process on;
worker_processes 4;
pid /tmp/aegisx-bench-cecd0n98/nginx.pid;
error_log /tmp/aegisx-bench-cecd0n98/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-cecd0n98/body;
    proxy_temp_path /tmp/aegisx-bench-cecd0n98/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;
    proxy_cache_path /tmp/aegisx-bench-cecd0n98/cache levels=1 keys_zone=zone:16m max_size=128m inactive=60s use_temp_path=off;
    upstream origin { server 127.0.0.1:59777; keepalive 256; }
    server {
        listen 127.0.0.1:36103 reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 127.0.0.1:59777;
            proxy_cache zone;
            proxy_cache_valid 200 60s;
            proxy_ignore_headers Cache-Control Expires Set-Cookie;
            proxy_pass http://origin;
        }
    }
}
